131	  primaryImage,
132	  hoverImage,
133	  images,
134	  swapOnHover,
135	  showControls,
136	  badge,
137	  onRemove,
138	  removeLabel,
139	  priority,
140	  onClick,
141	}: ZimmProductCardMediaProps) => {
142	  const intl = useIntl();
143	  const styles = useMultiStyleConfig(ZIMM_PRODUCT_CARD_MEDIA_RECIPE, {});
